package local.lito381.server;
import java.nio.file.Path;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Actual shared pair entry and existing mutexes, with bounded detached contention. No service/DB. */
public final class SourcePairedScopePlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}
 static void set(Object o,String k,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,k,v);}
 @SuppressWarnings("unchecked")static ThreadLocal<Object> scopes()throws Exception{var f=NativePlayerActionScope.class.getDeclaredField("current");f.setAccessible(true);return(ThreadLocal<Object>)f.get(null);}
 static void phase(ClientSession pc,String name)throws Exception{var f=ClientSession.class.getDeclaredField("phase");set(pc,"phase",Arrays.stream(f.getType().getEnumConstants()).filter(x->x.toString().equals(name)).findFirst().orElseThrow());}
 static void contention(ClientSession caster,ClientSession target,boolean reverse,boolean nested)throws Exception{
  var held=(reverse?target:caster);var missing=(reverse?caster:target);var ready=new CountDownLatch(1);var release=new CountDownLatch(1);var returned=new CountDownLatch(1);var failure=new AtomicReference<Throwable>();var ran=new AtomicBoolean();var clean=new AtomicBoolean();
  var blocker=new Thread(()->{missing.nativePlayerActionLock().lock();try{ready.countDown();try{if(!release.await(8,TimeUnit.SECONDS))throw new AssertionError("bounded blocker release");}catch(Throwable e){failure.compareAndSet(null,e);}}finally{missing.nativePlayerActionLock().unlock();}},"detached-pair-peer");
  var caller=new Thread(()->{held.nativePlayerActionLock().lock();try{var local=scopes();Object prior=local.get();if(nested){try(var outer=NativePlayerActionScope.enter(held)){Object root=local.get();int size=((Map<?,?>)CombatAccess.field(root,"members")).size();int depth=(int)CombatAccess.field(root,"depth");NativePairedCastSafety.run(caster,target,()->ran.set(true));clean.set(local.get()==root&&size==((Map<?,?>)CombatAccess.field(root,"members")).size()&&depth==(int)CombatAccess.field(root,"depth")&&held.nativePlayerActionLock().getHoldCount()==1&&!missing.nativePlayerActionLock().isHeldByCurrentThread());returned.countDown();}}else{NativePairedCastSafety.run(caster,target,()->ran.set(true));clean.set(local.get()==prior&&held.nativePlayerActionLock().getHoldCount()==1&&!missing.nativePlayerActionLock().isHeldByCurrentThread());returned.countDown();}}catch(Throwable e){failure.compareAndSet(null,e);}finally{held.nativePlayerActionLock().unlock();NativePlayerActionScope.unlocked(held);}},"detached-pair-caller");
  blocker.start();boolean prompt=false;try{check(ready.await(3,TimeUnit.SECONDS),"isolated missing lock actually owned");caller.start();prompt=returned.await(3,TimeUnit.SECONDS);}finally{release.countDown();blocker.join(4000);caller.join(4000);}check(!blocker.isAlive()&&!caller.isAlive(),"both bounded detached workers terminal");if(failure.get()!=null)throw new AssertionError("detached worker",failure.get());check(prompt,"rejected shared pair returns while peer still locked");check(!ran.get()&&clean.get(),"rejection runs no body, opens/registers no peer scope and preserves exact hold count");
 }
 public static void main(String[]args)throws Exception{
  var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);Object previous=rules.get(null);var local=scopes();Object prior=local.get();var hub=(GameHub)SourceSignedRecoveryPlan.unsafe().allocateInstance(GameHub.class);var caster=SourceSignedRecoveryPlan.shell(hub,"caster");var target=SourceSignedRecoveryPlan.shell(hub,"target");var calls=new AtomicInteger();
  try{local.remove();rules.set(null,null);check(!NativeSourcePairedScope.enabled(caster),"unloaded rules retain original fallback");NativePairedCastSafety.run(caster,target,()->calls.incrementAndGet());check(calls.get()==1,"unloaded exact original shared entry runs");var path=Path.of("detached-no-read");rules.set(null,new CombatRules.Snapshot(Map.of(),path,path,path,Set.of(),path));check(NativeSourcePairedScope.enabled(caster)&&!NativeSourcePairedScope.enabled(null),"in-memory loaded BATTLE route only");
   phase(caster,"WORLD");check(!NativeSourcePairedScope.enabled(caster),"WORLD uses exact original fallback");NativePairedCastSafety.run(caster,target,()->calls.incrementAndGet());check(calls.get()==2,"WORLD fallback body preserved");phase(caster,"BATTLE");
   NativePairedCastSafety.run(caster,target,()->{if(!caster.nativePlayerActionLock().isHeldByCurrentThread()||!target.nativePlayerActionLock().isHeldByCurrentThread())throw new AssertionError("both original pair locks");calls.incrementAndGet();});check(calls.get()==3&&!caster.nativePlayerActionLock().isLocked()&&!target.nativePlayerActionLock().isLocked()&&local.get()==null,"unowned pair executes once and restores original scope/locks");
   NativePairedCastSafety.run(caster,caster,()->{if(caster.nativePlayerActionLock().getHoldCount()!=1)throw new AssertionError("self one original mutex");calls.incrementAndGet();});check(calls.get()==4&&!caster.nativePlayerActionLock().isLocked()&&local.get()==null,"self shares original one-lock path");
   for(boolean reverse:new boolean[]{false,true}){var held=reverse?target:caster;var missing=reverse?caster:target;held.nativePlayerActionLock().lock();try{int before=calls.get();NativePairedCastSafety.run(caster,target,()->{if(held.nativePlayerActionLock().getHoldCount()!=1||missing.nativePlayerActionLock().getHoldCount()!=1)throw new AssertionError("preacquired pair exact counts");calls.incrementAndGet();});check(calls.get()==before+1&&held.nativePlayerActionLock().getHoldCount()==1&&!missing.nativePlayerActionLock().isLocked()&&local.get()==null,"one-held pair releases only its acquired peer");var boom=new IllegalStateException("detached-body");boolean exact=false;try{NativePairedCastSafety.run(caster,target,()->{throw boom;});}catch(IllegalStateException e){exact=e==boom;}check(exact&&held.nativePlayerActionLock().getHoldCount()==1&&!missing.nativePlayerActionLock().isLocked()&&local.get()==null,"original body exception propagates, scope and peer released");}finally{held.nativePlayerActionLock().unlock();NativePlayerActionScope.unlocked(held);}}
   caster.nativePlayerActionLock().lock();target.nativePlayerActionLock().lock();try{NativePairedCastSafety.run(caster,target,()->calls.incrementAndGet());check(caster.nativePlayerActionLock().getHoldCount()==1&&target.nativePlayerActionLock().getHoldCount()==1&&local.get()==null,"already-owned pair retains exact caller lock counts");}finally{target.nativePlayerActionLock().unlock();caster.nativePlayerActionLock().unlock();NativePlayerActionScope.unlocked(target);NativePlayerActionScope.unlocked(caster);}
   for(boolean reverse:new boolean[]{false,true})for(boolean nested:new boolean[]{false,true})contention(caster,target,reverse,nested);
   check(NativeSourcePairedScope.class.getDeclaredFields().length==0,"field-free helper retains no actor/Frame/Context/life/scope");check(local.get()==null,"shared scope restored after all detached paths");
  }finally{rules.set(null,previous);if(prior==null)local.remove();else local.set(prior);}check(rules.get(null)==previous&&local.get()==prior,"in-memory rules and original ThreadLocal restored");System.out.println("PASS"+cases+" shared paired scope actual-entry/contention/both-orientations/self/exception/fallback contracts; no bound cast/RNG/HP/IO/role/Main/database/game qualification");
 }
}
